INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Aktivitätsdiagramm nur für Softwareprozesse gedacht?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Geschäftsprozesse darstellbar"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Aktivitätsdiagramm?', 3, '[{"text": "Workflows visualisieren", "correct": true, "because": "Zeigt Prozessabläufe"}, {"text": "Hardwarezuordnung", "correct": false, "because": "Verteilungsdiagramm"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einem Aktivitätsdiagramm?', 5, '[{"text": "Aktivitäten", "correct": true, "because": "Zeigen Prozessschritte"}, {"text": "Entscheidungsknoten", "correct": true, "because": "Steuern Ablauf"}, {"text": "Farbanimation", "correct": false, "because": "Irrelevant"}, {"text": "Hardwareknoten", "correct": false, "because": "Verteilungsdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Aktivitätsdiagramme zeigen Prozesse. b) Sie ersetzen Sequenzdiagramme.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sequenz für Interaktionen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Aktivitätsdiagramm?', 4, '[{"text": "Ablaufreihenfolge", "correct": false, "because": "Kern des Diagramms"}, {"text": "Entscheidungspunkte", "correct": false, "because": "Steuern Workflow"}, {"text": "UI-Design", "correct": true, "because": "Kein Prozessaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Aktivitätsdiagramm auch Objekte zeigt?', 2, '[{"text": "Ja", "correct": true, "because": "Objektfluss möglich"}, {"text": "Nein", "correct": false, "because": "Nicht rein prozessbezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für einen Entscheidungspunkt?', 3, '[{"text": "Raute", "correct": true, "because": "UML-Standard für Entscheidungen"}, {"text": "Pfeil", "correct": false, "because": "Nur Übergang"}, {"text": "Rechteck", "correct": false, "because": "Aktivität"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten verbessern ein Aktivitätsdiagramm?', 5, '[{"text": "Start-/Endknoten", "correct": true, "because": "Definieren Prozessgrenzen"}, {"text": "Übergänge", "correct": true, "because": "Verbinden Schritte"}, {"text": "Datenfluss", "correct": false, "because": "Datenflussdiagramm"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Aktivitätsdiagramme zeigen Workflows. b) Sie sind für Hardware wichtig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hardware ist Verteilungsdiagramm"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein Aktivitätsdiagramm?', 4, '[{"text": "Aktivitäten", "correct": false, "because": "Prozessschritte"}, {"text": "Entscheidungen", "correct": false, "because": "Steuern Ablauf"}, {"text": "Netzwerkknoten", "correct": true, "because": "Verteilungsdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Aktivitätsdiagramm nur für Software?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Geschäftsprozesse"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beziehungen nutze ich in einem Aktivitätsdiagramm?', 4, '[{"text": "Übergänge", "correct": true, "because": "Verbinden Aktivitäten"}, {"text": "Objektfluss", "correct": true, "because": "Daten zwischen Schritten"}, {"text": "Abhängigkeiten", "correct": false, "because": "Komponentendiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Aktivitätsdiagramme nur Abläufe zeigen. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Fokus auf Prozessschritte"}, {"text": "Nein", "correct": false, "because": "Auch Objektfluss möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Aktivitätsdiagramm?', 3, '[{"text": "Ablaufklarheit", "correct": true, "because": "Fördert Verständnis"}, {"text": "Schnelle Zeichnung", "correct": false, "because": "Qualität zählt"}, {"text": "Technische Details", "correct": false, "because": "Nicht im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Aktivitätsdiagramme sind dynamisch. b) Sie zeigen Hardwarezuordnung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hardware ist Verteilungsdiagramm"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Aktivitätsdiagramm?', 5, '[{"text": "Prozessübersicht", "correct": true, "because": "Klarheit über Abläufe"}, {"text": "Entscheidungsvisualisierung", "correct": true, "because": "Zeigt Verzweigungen"}, {"text": "Hardwareplanung", "correct": false, "because": "Verteilungsdiagramm"}, {"text": "Code-Details", "correct": false, "because": "Nicht im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Aktivitätsdiagramm unwichtig?', 3, '[{"text": "Aktivitätsfluss", "correct": false, "because": "Kern der Darstellung"}, {"text": "Startpunkt", "correct": false, "because": "Definiert Beginn"}, {"text": "Blinkende Icons", "correct": true, "because": "Kein Prozessaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Zeigt ein Aktivitätsdiagramm auch Objekte?', 3, '[{"text": "Ja", "correct": true, "because": "Mit Objektfluss möglich"}, {"text": "Nein", "correct": false, "because": "Nicht rein prozessbezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Aktivitätsdiagramme für Tests nützlich sind?', 2, '[{"text": "Ja", "correct": true, "because": "Definieren Testabläufe"}, {"text": "Nein", "correct": false, "because": "Basis für Testfälle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Symbol wähle ich für eine Aktivität?', 4, '[{"text": "Abgerundetes Rechteck", "correct": true, "because": "UML-Standard"}, {"text": "Pfeil", "correct": false, "because": "Nur Übergang"}, {"text": "Kreis", "correct": false, "because": "Start-/Endpunkt"}]');
